  const agents = [["ASA-001","Risk triage",0.021,"Contained"],["ASA-004","Compliance mapper",0.031,"Observed"],["ASA-007","Evidence verifier",0.018,"Contained"],["ASA-012","Scenario analyst",0.047,"Review required"]];
