function CompliancePage() {
  const [frameworkFilter, setFrameworkFilter] = useState("All frameworks");
  const [domainFilter, setDomainFilter] = useState("All domains");
  const [statusFilter, setStatusFilter] = useState("All statuses");
  const [riskFilter, setRiskFilter] = useState("All risk levels");
  const [onlyGaps, setOnlyGaps] = useState(false);
  const [criticalOnly, setCriticalOnly] = useState(false);
  const [treatyOnly, setTreatyOnly] = useState(false);
  const [drawer, setDrawer] = useState<{ framework: string; domain: ControlDomain; status: CellStatus; ref: string } | null>(null);
  const rows = domains.filter(d => domainFilter === "All domains" || d.id === domainFilter).flatMap((domain, di) => frameworks.filter(f => frameworkFilter === "All frameworks" || frameworkFilter === f).map((framework, fi) => {
    const score = (di * 7 + fi * 11 + framework.length) % 17;
    const status = framework.includes("Interstellar") || framework.includes("Galactic") || framework.includes("CFE-1.0") || framework.includes("SGR-028") ? (score % 3 === 0 ? "PENDING" : score % 2 ? "PARTIAL" : "COMPLIANT") : framework.includes("SEC Rule") && domain.id === "CD-03" ? "COMPLIANT" : framework.includes("GDPR") && domain.id === "CD-07" ? "NOT_APPLICABLE" : score < 4 ? "NON_COMPLIANT" : score < 9 ? "PARTIAL" : score < 13 ? "PENDING" : "COMPLIANT";
    const st = status as CellStatus;
    const isCriticalFramework = ["EU AI Act", "DORA", "NIS2 Directive", "GDPR", "Fed SR 11-7"].includes(framework);
    const isTreaty = ["ICGC/GASO Accords", "Interstellar AI Governance Accord", "Galactic Treaty Framework", "CFE-1.0 Constitutional Framework", "Protocol SGR-028"].includes(framework);
    return { domain, framework, status: st, ref: controlReferences[(di + fi) % controlReferences.length], gap: st === "NON_COMPLIANT" || st === "PARTIAL" || st === "PENDING", isCriticalFramework, isTreaty, risk: domain.findings > 3 ? "High" : domain.findings > 1 ? "Medium" : "Low" };
  })).filter(r => !onlyGaps || r.gap).filter(r => !criticalOnly || r.isCriticalFramework).filter(r => !treatyOnly || r.isTreaty).filter(r => statusFilter === "All statuses" || r.status === statusFilter).filter(r => riskFilter === "All risk levels" || r.risk === riskFilter);
  const exportControls = () => downloadText("gien-oscal-control-crosswalk.json", JSON.stringify({ schema: "fictional-oscal-1.1.2-crosswalk", generatedAt: fmtUtc, source: "demo-only", controls: rows.map(r => ({ domain: r.domain.id, framework: r.framework, status: r.status, controlId: r.ref, verified: false })) }, null, 2), "application/json");
  return <><PageHeader title="Cross-Jurisdictional Compliance Matrix" subtitle="Filter fictional control-to-framework mappings and inspect the evidence expected for each cell."/><DemoBanner text="These are simulated crosswalk statuses—not legal determinations, certifications, or actual compliance findings."/><div className="metric-grid four"><MetricCard label="Framework catalogue" value={frameworks.length} detail="Public and fictional frameworks"/><MetricCard label="Mapped rows shown" value={rows.length} detail="Changes with active filters"/><MetricCard label="Illustrative gap rows" value={rows.filter(r=>r.gap).length} detail="Partial, pending, or non-compliant" tone="amber"/><MetricCard label="Treaty-grade scope" value="5 frameworks" detail="Fictional treaty mappings" tone="cyan"/></div>
  <section className="panel"><div className="filter-grid"><label>Framework<select value={frameworkFilter} onChange={e=>setFrameworkFilter(e.target.value)}><option>All frameworks</option>{frameworks.map(f=><option key={f}>{f}</option>)}</select></label><label>Control domain<select value={domainFilter} onChange={e=>setDomainFilter(e.target.value)}><option>All domains</option>{domains.map(d=><option key={d.id} value={d.id}>{d.id} · {d.name}</option>)}</select></label><label>Status<select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>All statuses</option>{frameworkStatuses.map(s=><option key={s}>{s}</option>)}</select></label><label>Risk level<select value={riskFilter} onChange={e=>setRiskFilter(e.target.value)}><option>All risk levels</option><option>Low</option><option>Medium</option><option>High</option></select></label></div><div className="toggle-filters"><label><input type="checkbox" checked={onlyGaps} onChange={e=>setOnlyGaps(e.target.checked)}/> Show only gaps</label><label><input type="checkbox" checked={criticalOnly} onChange={e=>setCriticalOnly(e.target.checked)}/> Critical frameworks only</label><label><input type="checkbox" checked={treatyOnly} onChange={e=>setTreatyOnly(e.target.checked)}/> Treaty-grade only</label><button className="outline-btn" onClick={() => {setFrameworkFilter("All frameworks");setDomainFilter("All domains");setStatusFilter("All statuses");setRiskFilter("All risk levels");setOnlyGaps(false);setCriticalOnly(false);setTreatyOnly(false);}}>Reset filters</button></div><div className="table-wrap matrix-wrap"><table className="matrix-table"><thead><tr><th>Domain / sub-control</th><th>Framework</th><th>OSCAL 1.1.2</th><th>Status</th><th>Risk level</th><th>Detail</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r.domain.id + r.framework}><td><strong>{r.domain.id}</strong><small className="cell-subtitle">{r.domain.name}</small></td><td>{r.framework}</td><td className="mono">{r.ref}</td><td><button className="matrix-state" onClick={() => setDrawer(r)}><StatusBadge status={r.status}/></button></td><td><StatusBadge status={r.risk === "High" ? "CRITICAL" : r.risk === "Medium" ? "ELEVATED" : "NOMINAL"}>{r.risk}</StatusBadge></td><td><button className="icon-button" onClick={() => setDrawer(r)} aria-label={"Inspect " + r.framework + " mapping"}><ChevronRight size={16}/></button></td></tr>)}</tbody></table></div></section>
  <section className="panel"><PanelTitle title="Framework summary cards" detail="Scores are calculated from the current simulated table selection, not from evidence validation."/><div className="framework-summary-grid">{frameworks.filter(f=>frameworkFilter==="All frameworks"||f===frameworkFilter).map(f=>{const sampleRows=rows.filter(r=>r.framework===f);const assessed=sampleRows.filter(r=>r.status==="COMPLIANT"||r.status==="NON_COMPLIANT"||r.status==="PARTIAL");const score=assessed.length?Math.round(100*assessed.filter(r=>r.status==="COMPLIANT").length/assessed.length):0;const gaps=sampleRows.filter(r=>r.status==="NON_COMPLIANT"||r.status==="PARTIAL"||r.status==="PENDING").length;return <article className="framework-summary-card" key={f}><strong>{f}</strong><div className="framework-summary-score">{score}%</div><ProgressBar label="Positive assessed status" value={score}/><small>{gaps} illustrative gaps / pending rows</small></article>;})}</div></section>
  <section className="panel"><PanelTitle title="OSCAL 1.1.2 validation panel" detail="Local mock validation fields; no schema validator is running"/><div className="validation-grid"><div><small>System Security Plan (SSP)</small><StatusBadge status="PENDING">Schema check not run</StatusBadge></div><div><small>Assessment Results JSON</small><StatusBadge status="PENDING">Schema check not run</StatusBadge></div><div><small>Artefact bundle Merkle root</small><strong className="mono">{demoHash("oscal-root-20261012").slice(0, 26)}…</strong></div><div><small>PQC signature verification</small><StatusBadge status="UNVERIFIED">No cryptographic verifier</StatusBadge></div></div><button className="primary-btn" onClick={exportControls}><Download size={15}/> Export machine-readable JSON</button></section>
  {drawer && <DetailDrawer title={drawer.framework} eyebrow={drawer.domain.id + " · CONTROL MAPPING"} onClose={() => setDrawer(null)}><h3>{drawer.domain.name}</h3><p>{drawer.domain.description}</p><div className="drawer-grid"><div><small>Framework reference</small><strong>{drawer.framework}</strong></div><div><small>OSCAL control ID</small><strong className="mono">{drawer.ref}</strong></div><div><small>Assessment status</small><StatusBadge status={drawer.status}/></div><div><small>Assessment timestamp</small><strong>{fmtUtc}</strong></div></div><h3>OPA-Rego policy example</h3><CodeBlock language="rego" code={'package gien.supervisory\\n\\ndefault allow := false\\n\\nallow if {\\n  input.control_id == "' + drawer.ref + '"\\n  input.evidence.present == true\\n  input.evidence.source_verified == true\\n}\\n\\n# Demo policy only; not a deployed control.'}/><h3>Fictional evidence artefacts</h3><div className="mono hash-line">{demoHash(drawer.framework + drawer.domain.id)}</div><div className="mono hash-line">{demoHash(drawer.ref + "evidence")}</div><h3>Remediation plan</h3><p>{drawer.status === "COMPLIANT" ? "Retain the evidence link, schedule periodic review, and independently re-evaluate applicability." : "Assign a control owner, validate applicability, attach source evidence, record target date, and re-run the assessment. No remediation completion is claimed."}</p><CodeBlock language="assessment JSON" code={JSON.stringify({ framework: drawer.framework, domain: drawer.domain.id, controlId: drawer.ref, status: drawer.status, source: "simulation", verified: false, assessedAt: fmtUtc }, null, 2)}/></DetailDrawer>}</>;
}
