  {step===2&&<div className="section-checklist">{sections.map(s=><label className="section-check" key={s}><input type="checkbox" checked={included.includes(s)} onChange={e=>toggle(s,e.target.checked)}/><span><strong>{s}</strong><small>Fictional evidence block · no verified source attached</small></span></label>)}</div>}
