  const contextValue: RoleContextValue = { role, setRole, phase: "VI-δ", evaluationWindow: "2026-10-12 09:00 UTC", alerts: alertCount };
  const currentTitle = navigation.flatMap(g=>g.items).find(item=>item.path===location.pathname)?.label ?? "Daily supervisory brief";
